// ======================
// CAPTURAR UBICACIÓN ORIGINAL
// ======================
const ubicacionOriginalTexto = ($json["Ubicación"] || "");

// ======================
// FUNCIÓN DE NORMALIZACIÓN MEJORADA
// ======================
function norm(s) {
  return (s || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // Quita tildes
    .replace(/[,.-]/g, " ") // Cambia signos de puntuación por espacios
    .replace(/\s+/g, " ") // Limpia espacios dobles
    .trim();
}

// ======================
// FUNCIÓN PARA CAPITALIZAR
// ======================
const capitalizar = (str) => {
  if (!str) return "";
  return str.toString().trim().split(" ")
    .map(p => p.charAt(0).toUpperCase() + p.slice(1).toLowerCase())
    .join(" ");
};

// ======================
// VALIDAR Y NORMALIZAR RIF
// ======================
let rif = ($json["RIF"] || "")
  .toString()
  .trim()
  .toUpperCase()
  .replace(/\s+/g, "");

if (!rif.startsWith("J-")) {
  rif = rif.replace(/^[A-Z]-?/i, "");
  rif = `J-${rif}`;
}

// ======================
// VALIDAR Y NORMALIZAR WHATSAPP
// ======================
let whatsapp = ($json["WhatsApp"] || "").toString().trim().replace(/\s+/g, "");

if (whatsapp) {
  if (whatsapp.startsWith('0') || whatsapp.startsWith('58')) {
    whatsapp = '+' + whatsapp;
  } else if (whatsapp.startsWith('4')) {
    whatsapp = '0' + whatsapp;
  }
}

