const ubicacionNorm = norm(ubicacionOriginalTexto);
let claveEstado = null;

for (const clave of Object.keys(estadosMap)) {
  const regex = new RegExp(`\\b${clave}\\b`, 'i');
  if (regex.test(ubicacionNorm)) {
    claveEstado = clave;
    break;
  }
}

if (!claveEstado) {
  for (const [alias, clave] of Object.entries(aliases)) {
    const regex = new RegExp(`\\b${alias}\\b`, 'i');
    if (regex.test(ubicacionNorm)) {
      claveEstado = clave;
      break;
    }
  }
}

const estadoDetectado = claveEstado ? estadosMap[claveEstado] : "Sin Asignar";

let interes = $json["Interes"] || "";
if (Array.isArray(interes)) {
  interes = interes.join(", ");
} else if (typeof interes === "string") {
  try {
    const parsed = JSON.parse(interes);
    if (Array.isArray(parsed)) interes = parsed.join(", ");
  } catch (e) {
    interes = interes.trim();
  }
}

const tipo = ($json["Tipo"] || "").toString().trim().toUpperCase();

const { "Ubicación": _, ...restoDatos } = $json;

return [{
  json: {
    ...restoDatos,
    "Nombre de la empresa": capitalizar($json["Nombre de la empresa"] || ""),
    RIF: rif,
    WhatsApp: whatsapp,
    "Ubicacion detalle": ubicacionOriginalTexto,
    Estado: estadoDetectado,
    Interes: interes,
    Tipo: tipo
  }
}];

const mysqlOutput = $('Asignar Vendedor Carcar').item.json;
const seller_id = mysqlOutput.seller_id || (mysqlOutput[0] && mysqlOutput[0].seller_id);
