const asignacion = mysqlOutput.asignacion || (mysqlOutput[0] && mysqlOutput[0].asignacion);
const leadData = $('Normalizar Datos del Lead').item.json;
let telefono = (leadData.WhatsApp || "").toString().replace(/\D/g, "");
if (telefono.startsWith("0")) telefono = telefono.substring(1);
if (!telefono.startsWith("58")) telefono = "58" + telefono;
const nombreVendedor = name || "nuestro equipo";
const mensaje = `Hola, soy ${nombreVendedor} de Supricom. El equipo de marketing me envió tus datos para darte atención prioritaria. Mi objetivo es asegurar que tu negocio cuente con el respaldo de un mayorista en tecnología que necesitas.`;
const whatsappLink = `https://wa.me/${telefono}?text=${encodeURIComponent(mensaje)}`;
return [{ json: { ...leadData, Vendedor: name || "No asignado", seller_id: seller_id || 0, AsignacionActual: parseInt(asignacion) || 0, WhatsAppLink: whatsappLink } }];

